public class Solution {
  /**
   * 前向星（CSR）+ Kahn 拓扑 + DP，全程迭代、零装箱：
   *   dp[v] = 以 v 结尾的最长路径耗时 = nodeMillis[v] + max(dp[pred])
   * 环检测靠"拓扑排出的节点数 < n"，不依赖 DFS 三色标记，因此菱形交叉边不会被误判。
   * 重边只是让松弛多做一次（幂等），indeg 的 +1/-1 也按边发生次数成对抵消，结果不受影响。
   */
  public static long criticalPathMillis(int n, int[] edgeFrom, int[] edgeTo, int[] nodeMillis) {
    if (edgeFrom.length != edgeTo.length) throw new IllegalArgumentException("edge arrays must be parallel");
    if (nodeMillis.length != n) throw new IllegalArgumentException("duration array size mismatch");
    if (n == 0) return 0L;
    int m = edgeFrom.length;
    int[] head = new int[n];
    java.util.Arrays.fill(head, -1);            // 忘了填 -1 会把"无边"当成"0 号边"
    int[] to = new int[m];
    int[] next = new int[m];
    int[] indeg = new int[n];
    for (int e = 0; e < m; e++) {
      int u = edgeFrom[e];
      int v = edgeTo[e];
      if (u < 0 || u >= n || v < 0 || v >= n) throw new IllegalArgumentException("edge endpoint out of range");
      to[e] = v;
      next[e] = head[u];
      head[u] = e;
      indeg[v]++;
    }
    int[] queue = new int[n];                   // 手写 int 队列，避免 ArrayDeque<Integer> 装箱
    int qh = 0;
    int qt = 0;
    long[] dp = new long[n];
    for (int v = 0; v < n; v++) {
      dp[v] = nodeMillis[v];
      if (indeg[v] == 0) queue[qt++] = v;
    }
    int settled = 0;
    long answer = 0L;
    while (qh < qt) {
      int u = queue[qh++];
      settled++;
      if (dp[u] > answer) answer = dp[u];
      for (int e = head[u]; e != -1; e = next[e]) {
        int v = to[e];
        long candidate = dp[u] + nodeMillis[v];  // long 域累加
        if (candidate > dp[v]) dp[v] = candidate;
        if (--indeg[v] == 0) queue[qt++] = v;
      }
    }
    return settled == n ? answer : -1L;         // 有环（含自环）时排不完
  }
}

runner.naiveSolution:
public class Solution {
  // 朴素：递归 DFS + 一个 boolean[] visited，把"访问过"当成"在递归栈上"。
  // 于是菱形图的交叉边被当成回边 -> 误报环（长链还会 StackOverflowError）。
  static java.util.List<java.util.List<Integer>> graph;
  static boolean[] visited;
  static int[] dur;

  public static long criticalPathMillis(int n, int[] edgeFrom, int[] edgeTo, int[] nodeMillis) {
    graph = new java.util.ArrayList<java.util.List<Integer>>();
    for (int v = 0; v < n; v++) graph.add(new java.util.ArrayList<Integer>());
    for (int e = 0; e < edgeFrom.length; e++) graph.get(edgeFrom[e]).add(edgeTo[e]);
    visited = new boolean[n];
    dur = nodeMillis;
    if (n == 0) return 0L;
    long best = 0L;
    for (int v = 0; v < n; v++) {
      long value = dfs(v);
      if (value < 0) return -1L;
      if (value > best) best = value;
    }
    return best;
  }

  static long dfs(int u) {
    if (visited[u]) return -1L;                 // BUG：交叉边 != 回边
    visited[u] = true;
    long best = 0L;
    for (int v : graph.get(u)) {
      long sub = dfs(v);
      if (sub < 0) return -1L;
      if (sub > best) best = sub;
    }
    return best + dur[u];
  }
}
